SELECT da.id, da.patient_id, p.name AS patient_name, da.doctor_id, u.name AS doctor_name, da.assign_date, da.assigner_id, u2.name AS assigner_name, da.status, da.remarks FROM doctor_assignment da LEFT JOIN patient p ON da.patient_id = p.id LEFT JOIN doctor d ON da.doctor_id = d.id LEFT JOIN user u ON d.user_id = u.id LEFT JOIN user u2 ON da.assigner_id = u2.id
AND da.patient_id = #{patientId}
AND da.doctor_id = #{doctorId}
ORDER BY da.assign_date DESC, da.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM doctor_assignment da


        AND da.patient_id = #{patientId}


        AND da.doctor_id = #{doctorId}
